  7	public final class BreadthFirstSearch {
  8	
  9	    public static final class Graph {
 10	        private final List<List<Integer>> adjacencyList;
 11	
 12	        private Graph(int vertexCount) {
 13	            adjacencyList = new ArrayList<>(vertexCount);
 14	            for (int vertex = 0; vertex < vertexCount; vertex++) {
 15	                adjacencyList.add(new ArrayList<>());
 16	            }
 17	        }
 18	
 19	        public static Graph create(int vertexCount) {
 20	            if (vertexCount < 0) {
 21	                throw new IllegalArgumentException("vertexCount must be non-negative: " + vertexCount);
 22	            }
 23	            return new Graph(vertexCount);
 24	        }
 25	
 26	        public int vertexCount() {
 27	            return adjacencyList.size();
 28	        }
 29	
 30	        public void addUndirectedEdge(int u, int v) {
 31	            validateVertex(u);
 32	            validateVertex(v);
 33	
 34	            adjacencyList.get(u).add(v);
 35	            adjacencyList.get(v).add(u);
 36	        }
 37	
 38	        public void addDirectedEdge(int from, int to) {
 39	            validateVertex(from);
 40	            validateVertex(to);
 41	
 42	            adjacencyList.get(from).add(to);
 43	        }
 44	
 45	        private List<Integer> neighbors(int vertex) {
 46	            return adjacencyList.get(vertex);
 47	        }
 48	
 49	        private void validateVertex(int vertex) {
 50	            if (vertex < 0 || vertex >= adjacencyList.size()) {
 51	                throw new IllegalArgumentException("vertex out of bounds: " + vertex);
 52	            }
 53	        }
 54	    }
 55	
 56	    private BreadthFirstSearch() {
 57	        // Utility class.
 58	    }
 59	
 60	    private static void bfsComponent(Graph graph, int source, boolean[] visited, List<Integer> result) {
 61	        Deque<Integer> queue = new ArrayDeque<>();
 62	        visited[source] = true;
 63	        queue.addLast(source);
 64	
 65	        while (!queue.isEmpty()) {
 66	            int current = queue.removeFirst();
 67	            result.add(current);
 68	
 69	            for (int neighbor : graph.neighbors(current)) {
 70	                if (!visited[neighbor]) {
 71	                    visited[neighbor] = true;
 72	                    queue.addLast(neighbor);
 73	                }
 74	            }
 75	        }
 76	    }
 77	
 78	    public static List<Integer> bfs(Graph graph) {
 79	        Objects.requireNonNull(graph, "graph");
 80	
 81	        int vertexCount = graph.vertexCount();
 82	        boolean[] visited = new boolean[vertexCount];
 83	        List<Integer> result = new ArrayList<>(vertexCount);
 84	
 85	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 86	            if (!visited[vertex]) {
 87	                bfsComponent(graph, vertex, visited, result);
 88	            }
 89	        }
 90	        return result;
 91	    }
 92	
 93	    public static List<Integer> bfsFromSource(Graph graph, int source) {
 94	        Objects.requireNonNull(graph, "graph");
 95	        graph.validateVertex(source);
 96	
 97	        boolean[] visited = new boolean[graph.vertexCount()];
 98	        List<Integer> result = new ArrayList<>();
 99	        bfsComponent(graph, source, visited, result);
100	        return result;
101	    }
