104	        Graph graph = Graph.create(6);
105	
106	        graph.addUndirectedEdge(1, 2);
107	        graph.addUndirectedEdge(2, 0);
108	        graph.addUndirectedEdge(0, 3);
109	        graph.addUndirectedEdge(4, 5);
110	
111	        List<Integer> traversal = bfs(graph);
112	        for (int vertex : traversal) {
113	            System.out.print(vertex + " ");
114	        }
115	    }
116	}
